"use client"

import { useWallet } from "@/lib/useWallet"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { useState } from "react"

export function WalletConnection() {
  const { account, isConnected, isLoading, error, connectWallet } = useWallet()
  const [copied, setCopied] = useState(false)

  const handleCopyAddress = () => {
    if (account) {
      navigator.clipboard.writeText(account)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    }
  }

  if (isConnected && account) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">💰 Connected</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            <p className="text-sm text-gray-600">Account</p>
            <div className="flex items-center gap-2 bg-gray-50 p-2 rounded">
              <code className="text-sm flex-1 break-all">{account}</code>
              <button onClick={handleCopyAddress} className="p-1 hover:bg-gray-200 rounded text-lg">
                {copied ? "✓" : "📋"}
              </button>
            </div>
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">💰 Connect Wallet</CardTitle>
      </CardHeader>
      <CardContent>
        <Button onClick={connectWallet} disabled={isLoading} className="w-full">
          {isLoading ? "Connecting..." : "Connect MetaMask"}
        </Button>
        {error && <p className="text-sm text-red-600 mt-2">{error}</p>}
      </CardContent>
    </Card>
  )
}
