"use client"

import { useState, useEffect } from "react"
import { walletManager } from "./wallet-manager"

export function useWallet() {
  const [account, setAccount] = useState<string | null>(null)
  const [isConnected, setIsConnected] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    // Check if already connected
    const initializeWallet = async () => {
      try {
        const currentUser = walletManager.getCurrentUser()
        if (currentUser) {
          setAccount(currentUser)
          setIsConnected(true)
        } else {
          // In mock mode, auto-connect on mount
          if (typeof window !== "undefined" && localStorage.getItem("useMockContracts") === "true") {
            console.log("[v0] Auto-connecting wallet in mock mode...")
            const address = await walletManager.connectWallet()
            setAccount(address)
            setIsConnected(true)
          }
        }
      } catch (err) {
        console.error("[v0] Wallet initialization error:", err)
      }
    }

    initializeWallet()
  }, [])

  const connectWallet = async () => {
    setIsLoading(true)
    setError(null)
    try {
      const address = await walletManager.connectWallet()
      setAccount(address)
      setIsConnected(true)
    } catch (err: any) {
      setError(err.message)
      setIsConnected(false)
    } finally {
      setIsLoading(false)
    }
  }

  return {
    account,
    isConnected,
    isLoading,
    error,
    connectWallet,
    walletManager,
  }
}
